#include "opensim/services/library_inventory_caps.hpp"
#include <iostream>
using namespace opensim;using namespace services;
namespace {
framework::Uuid id(int n){auto tail=std::to_string(n);return framework::Uuid("00000000-0000-0000-0000-"+std::string(12-tail.size(),'0')+tail);}
std::string hex(std::string_view value){std::string result;constexpr char d[]="0123456789abcdef";for(unsigned char c:value){result+=d[c>>4];result+=d[c&15];}return result;}
InventoryItem sample(int seed,framework::Uuid key){InventoryItem item;item.id=key;item.owner=id(200);item.parent=id(201);item.asset_id=id(500+seed);item.name="library <&> é";item.description="library description";item.flags=seed%2?-1:0x1234;item.asset_type=seed-5;item.inventory_type=seed%3;item.current_permissions=seed%2?-1:0;item.base_permissions=123;item.creator_id=id(44).str();item.group_id=seed%2?id(45):framework::Uuid{};item.group_owned=seed%2;item.sale_price=seed%3;item.sale_type=seed%4;return item;}
std::string probe(int seed,int count,int mode){int calls=0;std::string trace;LibraryItemBackend backend;backend.root_owner=id(200);backend.get_items=[&](const auto& ids)->std::optional<FetchInventory2Core::Items>{++calls;for(auto key:ids){if(!trace.empty())trace+=',';trace+=key.str();}if(mode&16)throw std::runtime_error("PROVIDER");if(mode&32)return {};FetchInventory2Core::Items result;for(std::size_t i=0;i<ids.size();++i)result.push_back((mode&512)||ids[i].is_zero()||i%3==2?std::nullopt:std::optional{sample(seed,ids[i])});return result;};FetchLibrary2Core core(mode&8?framework::Uuid{}:id(42),mode&4?std::nullopt:std::optional{backend});InventoryBadRequests bad([]{return 0;});if(mode&1)bad.add(id(2));network::Value map=network::Value::object({}),array;array.kind=network::Value::Kind::Array;for(int i=0;i<count;++i){auto item=network::Value::object({});if(!(mode&256)){network::Value key;key.kind=network::Value::Kind::Uuid;key.text=id(i+1).str();item.set("item_id",key);}if(mode&128)item=network::Value("wrong");array.array.push_back(item);}if(mode&64)array=network::Value("wrong");map.set("items",array);std::string result;try{auto response=core.handle(map,mode&2?nullptr:&bad);result=std::to_string(response.status)+":"+hex(response.body);}catch(const std::runtime_error& e){result=std::string_view(e.what())=="PROVIDER"?"PROVIDER":"CAST";}catch(const std::exception&){result="CAST";}return result+"|"+std::to_string(calls)+"|"+trace;}
std::string unhex(const std::string& value){if(value=="-")return {};std::string out;for(std::size_t i=0;i<value.size();i+=2)out+=static_cast<char>(std::stoi(value.substr(i,2),nullptr,16));return out;}
std::string http_probe(int seed,int mode,const std::string& method,const std::string& body){int calls=0;std::string trace;LibraryItemBackend backend;backend.root_owner=id(200);backend.get_items=[&](const auto& ids)->std::optional<FetchInventory2Core::Items>{++calls;for(auto key:ids){if(!trace.empty())trace+=',';trace+=key.str();}if(mode&16)throw std::runtime_error("PROVIDER");if(mode&32)return {};FetchInventory2Core::Items out;for(std::size_t i=0;i<ids.size();++i)out.push_back(ids[i].is_zero()||i%3==2?std::nullopt:std::optional{sample(seed,ids[i])});return out;};auto core=std::make_shared<FetchLibrary2Core>(mode&8?framework::Uuid{}:id(42),mode&4?std::nullopt:std::optional{backend});auto bad=std::make_shared<InventoryBadRequests>([]{return 0;});if(mode&1)bad->add(id(2));FetchLibrary2Route route("/library",core,mode&2?nullptr:bad);network::HttpRequest request;request.method=method;request.body=body;auto response=route.handle(request);return std::to_string(response.status)+":"+hex(response.body)+"|"+std::to_string(route.requests_received.load())+"|"+std::to_string(route.requests_handled.load())+"|"+std::to_string(calls)+"|"+trace;}
int checks=0;void check(bool value,const char* label){++checks;if(!value)throw std::runtime_error(label);}
void run(){check(http_probe(1,0,"GET","{}")=="404:|1|0|0|","route method404 before parse");check(http_probe(1,0,"POST","bad")=="400:|1|0|0|","route parse400");check(http_probe(1,0,"POST","{}")=="500:|1|1|0|","route core cast500");check(http_probe(1,16,"POST","{\"items\":[]}")=="500:|1|1|1|","route provider failure500");check(probe(1,3,2)=="404:|0|","null cache404");check(probe(1,3,4)=="404:|0|","missing library404");check(probe(1,3,8)=="404:|0|","zero agent404");check(probe(1,3,64)=="CAST|0|","invalid array cast");check(probe(1,3,16).starts_with("PROVIDER|1|"),"library provider error propagated");check(probe(1,3,1).ends_with("00000000-0000-0000-0000-000000000000"),"filtered ID keeps zero tail");check(probe(1,1,0).find(hex("<key>flags</key><integer>-1</integer>"))!=std::string::npos,"library item keeps full flags");bool failed=false;try{FetchLibrary2Core invalid(id(42),LibraryItemBackend{});}catch(const std::invalid_argument&){failed=true;}check(failed,"present library missing root rejected at construction");}
}
int main(int argc,char**argv){try{if(argc==2&&std::string_view(argv[1])=="--http"){int seed,mode;std::string method,body;while(std::cin>>seed>>mode>>method>>body)std::cout<<http_probe(seed,mode,method,unhex(body))<<'\n';return 0;}if(argc==2&&std::string_view(argv[1])=="--probe"){int seed,count,mode;while(std::cin>>seed>>count>>mode)std::cout<<probe(seed,count,mode)<<'\n';return 0;}run();std::cout<<"PASS: "<<checks<<" library inventory capability checks\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
